<?php require_once __DIR__.'/auth.php'; api_auth(); if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;} $old=$_POST['old_password']??'';$new=$_POST['new_password']??'';if(!password_verify($old,ADMIN_PASS_HASH)||strlen($new)<8){http_response_code(422);echo json_encode(['error'=>'Invalid current password or new password too short']);exit;} $hash=password_hash($new,PASSWORD_DEFAULT);$cfg=__DIR__.'/../admin/config.php';$s=file_get_contents($cfg);$s=preg_replace("/define\('ADMIN_PASS_HASH',\s*'[^']*'\);/", "define('ADMIN_PASS_HASH', '".addslashes($hash)."');", $s);file_put_contents($cfg,$s,LOCK_EX);echo json_encode(['ok'=>true]);
